const schema = `CREATE TABLE IF NOT EXISTS tracker_state (
  user_id TEXT PRIMARY KEY,
  payload TEXT NOT NULL,
  updated_at INTEGER NOT NULL
);`;

function userId(request) {
  return request.headers.get("oai-authenticated-user-id") || "private-owner";
}

async function ensureDb(db) {
  await db.prepare(schema).run();
}

function safeName(name) {
  return String(name || "document.pdf").replace(/[^a-zA-Z0-9._-]+/g, "_").slice(-120);
}

async function handleFile(request, env) {
  if (!env.BUCKET) return Response.json({error:"File storage is not configured."}, {status:503});
  const id = userId(request);
  const url = new URL(request.url);
  if (request.method === "GET") {
    const key = url.searchParams.get("key") || "";
    if (!key || !key.startsWith(id + "/")) return new Response("Not found", {status:404});
    const object = await env.BUCKET.get(key);
    if (!object) return new Response("Not found", {status:404});
    const headers = new Headers();
    object.writeHttpMetadata(headers);
    headers.set("content-disposition", "inline; filename=\"" + safeName(key.split("/").pop()) + "\"");
    headers.set("cache-control", "private, max-age=3600");
    return new Response(object.body, {headers});
  }
  if (request.method === "POST") {
    const form = await request.formData();
    const file = form.get("file");
    const appId = String(form.get("appId") || "");
    const kind = String(form.get("kind") || "");
    if (!(file instanceof File) || file.type !== "application/pdf" || !appId || !["resume","cover"].includes(kind)) return Response.json({error:"Only resume and cover-letter PDFs are supported."}, {status:400});
    if (file.size > 15 * 1024 * 1024) return Response.json({error:"PDF is too large."}, {status:413});
    const key = id + "/" + appId + "/" + kind + "/" + crypto.randomUUID() + "-" + safeName(file.name);
    await env.BUCKET.put(key, file.stream(), {httpMetadata:{contentType:"application/pdf"}, customMetadata:{userId:id, appId, kind, originalName:file.name}});
    return Response.json({file:{key, name:file.name, type:"application/pdf", size:file.size, uploadedAt:Date.now()}});
  }
  return new Response("Method Not Allowed", {status:405});
}

async function handleApi(request, env) {
  if (!env.DB) return new Response(JSON.stringify({error:"Database is not configured."}), {status:503, headers:{"content-type":"application/json"}});
  await ensureDb(env.DB);
  const id = userId(request);
  if (request.method === "GET") {
    const row = await env.DB.prepare("SELECT payload FROM tracker_state WHERE user_id = ?1").bind(id).first();
    return Response.json({state: row ? JSON.parse(row.payload) : null});
  }
  if (request.method === "PUT") {
    const body = await request.json();
    if (!body || typeof body.state !== "object") return Response.json({error:"Invalid tracker state."}, {status:400});
    const payload = JSON.stringify(body.state);
    await env.DB.prepare("INSERT INTO tracker_state(user_id,payload,updated_at) VALUES(?1,?2,?3) ON CONFLICT(user_id) DO UPDATE SET payload=excluded.payload, updated_at=excluded.updated_at").bind(id, payload, Date.now()).run();
    return Response.json({ok:true, updatedAt:Date.now()});
  }
  return new Response("Method Not Allowed", {status:405});
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname === "/api/files") {
      try { return await handleFile(request, env); }
      catch (error) { return Response.json({error: "File request failed."}, {status:500}); }
    }
    if (url.pathname === "/api/state") {
      try { return await handleApi(request, env); }
      catch (error) { return Response.json({error: "Storage request failed."}, {status:500}); }
    }
    if (url.pathname !== "/") return new Response("Not found", {status:404});
    return new Response(page, {headers:{"content-type":"text/html; charset=utf-8"}});
  }
};
